package com.aiservice.infrastructure.external;
import com.aiservice.application.port.out.AiProvider; import com.aiservice.domain.exception.ProviderException; import com.aiservice.infrastructure.persistence.repository.AiSettingsRepository; import com.aiservice.infrastructure.security.AiSecretProtector; import java.util.*; import org.springframework.context.annotation.Primary; import org.springframework.core.env.Environment; import org.springframework.stereotype.Component; import org.springframework.web.client.*; import tools.jackson.databind.*;
@Component @Primary public class RuntimeAiProviderResolver implements AiProvider { private final AiSettingsRepository settings; private final AiSecretProtector protector; private final GeminiAdapter fallback; private final RestClient.Builder builder; private final ObjectMapper mapper; private final Environment env; public RuntimeAiProviderResolver(AiSettingsRepository s,AiSecretProtector p,GeminiAdapter f,RestClient.Builder b,ObjectMapper m,Environment e){settings=s;protector=p;fallback=f;builder=b;mapper=m;env=e;}
 public String generateQuestions(String source,String request){return call(source,request,"generation");} public String analyze(String source,String request){return call(source,request,"analysis");} public String chat(String source,String request){return call(source,request,"chat");} public String systemHelp(String source,String request){return call(source,request,"system-help");}
 private String call(String source,String request,String purpose){var c=settings.findAll().stream().findFirst().orElse(null);if(c==null||c.provider==null)return environmentFallback(source,request,purpose);if(c.provider.equals("GEMINI")){if(c.apiKeyEncrypted==null||c.apiKeyEncrypted.isBlank())return environmentFallback(source,request,purpose);String runtimeKey=protector.decrypt(c.apiKeyEncrypted);return purpose.equals("system-help")?fallback.systemHelp(source,request,runtimeKey,c.model):purpose.equals("analysis")?fallback.analyze(source,request,runtimeKey,c.model):purpose.equals("chat")?fallback.chat(source,request,runtimeKey,c.model):fallback.generateQuestions(source,request,runtimeKey,c.model);}if(!Set.of("OPENAI","MISTRAL").contains(c.provider))throw new ProviderException("Unsupported AI provider",false,null);if(c.apiKeyEncrypted==null||c.apiKeyEncrypted.isBlank())throw new ProviderException("AI provider credential is not configured",false,null);String key=protector.decrypt(c.apiKeyEncrypted);String endpoint=env.getProperty("ai.provider.openai-url","https://api.openai.com/v1/chat/completions");String prompt="You are the HAU QM AI assistant. Return only valid JSON when requested.\nCONTEXT:\n"+source+"\nREQUEST:\n"+request;Map<String,Object> body=Map.of("model",c.model,"messages",List.of(Map.of("role","user","content",prompt)),"temperature",0.2);try{String raw=builder.build().post().uri(endpoint).header("Authorization","Bearer "+key).body(body).retrieve().body(String.class);JsonNode n=mapper.readTree(raw);JsonNode text=n.at("/choices/0/message/content");if(!text.isTextual())throw new ProviderException("Provider returned no text",false,null);return stripFence(text.asText());}catch(HttpClientErrorException e){throw new ProviderException(e.getStatusCode().value()==401?"Invalid AI provider key":"Provider rejected request",e.getStatusCode().is5xxServerError(),e);}catch(ResourceAccessException e){throw new ProviderException("Provider timeout or unavailable",true,e);}catch(ProviderException e){throw e;}catch(Exception e){throw new ProviderException("Malformed provider response",false,e);}}
 private String environmentFallback(String source,String request,String purpose){return purpose.equals("system-help")?fallback.systemHelp(source,request):purpose.equals("analysis")?fallback.analyze(source,request):purpose.equals("chat")?fallback.chat(source,request):fallback.generateQuestions(source,request);}
 private String stripFence(String value){String text=value==null?"":value.trim();if(text.startsWith("```")){int first=text.indexOf('\n'),last=text.lastIndexOf("```");if(first>=0&&last>first)return text.substring(first+1,last).trim();}return text;}
}
